const message = $json.message || {};
const chatId = message.chat?.id;
const text = (message.text || '').trim();
const userName = message.from?.first_name || 'usuario';

if (!chatId) {
  return [{ json: { ignore: true } }];
}

const store = $getWorkflowStaticData('global');
if (!store.sessions) {
  store.sessions = {};
}

if (!store.sessions[chatId]) {
  store.sessions[chatId] = {
    stage: 'idle',
    nombre_completo: null,
    cedula_identidad: null,
    email: null,
    curso_id: null,
    curso_nombre: null,
    metodo_pago: null
  };
}

const session = store.sessions[chatId];
const normalized = text.toLowerCase();

if (normalized === '/start' || normalized === '/inscribirme' || normalized === 'inscribirme') {
  store.sessions[chatId] = {
    stage: 'nombre',
    nombre_completo: null,
    cedula_identidad: null,
    email: null,
    curso_id: null,
    curso_nombre: null,
    metodo_pago: null
  };

  return [{
    json: {
      chatId,
      responseType: 'message',
      response: `Hola ${userName} 👋\n\nSoy el Agente de Gestión de Inscripciones.\n\nPara comenzar tu inscripción, necesito algunos datos.\n\nPor favor, indica tu nombre completo:`,
      stage: 'nombre'
    }
  }];
}

if (normalized === '/cancelar' || normalized === 'cancelar') {
  delete store.sessions[chatId];

  return [{
    json: {
      chatId,
      responseType: 'message',
      response: 'La inscripción ha sido cancelada. Cuando quieras comenzar nuevamente, escribe /inscribirme.'
    }
  }];
}

if (session.stage === 'idle') {
  return [{
    json: {
      chatId,
      responseType: 'message',
      response: 'Hola 👋 Para realizar una inscripción escribe /inscribirme.\n\nTambién puedes escribir /cancelar para cancelar una inscripción en curso.'
    }
  }];
}

if (session.stage === 'nombre') {
  if (text.length < 5 || !text.includes(' ')) {
    return [{
      json: {
        chatId,
        responseType: 'message',
        response: 'El nombre parece estar incompleto. Por favor, escribe tu nombre y apellido completos.',
        stage: 'nombre'
      }
    }];
  }

  session.nombre_completo = text;
  session.stage = 'cedula';

  return [{
    json: {
      chatId,
      responseType: 'message',
      response: 'Perfecto. Ahora indica tu documento de identidad (cédula):',
      stage: 'cedula'
    }
  }];
}

if (session.stage === 'cedula') {
  const cedula = text.replace(/[^0-9A-Za-z-]/g, '');

  if (cedula.length < 5) {
    return [{
      json: {
        chatId,
        responseType: 'message',
        response: 'El documento de identidad no parece válido. Por favor, intenta nuevamente.',
        stage: 'cedula'
      }
    }];
  }

  session.cedula_identidad = cedula;
  session.stage = 'email';

  return [{
    json: {
      chatId,
      responseType: 'message',
      response: 'Gracias. Ahora indica tu correo electrónico:',
      stage: 'email'
    }
  }];
}

if (session.stage === 'email') {
  const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;

  if (!emailRegex.test(text)) {
    return [{
      json: {
        chatId,
        responseType: 'message',
        response: 'El correo electrónico ingresado no es válido. Por favor, escribe un correo válido, por ejemplo: nombre@correo.com',
        stage: 'email'
      }
    }];
  }

  session.email = text.toLowerCase();
  session.stage = 'curso';

  return [{
    json: {
      chatId,
      responseType: 'courses_request',
      stage: 'curso'
    }
  }];
}

if (session.stage === 'curso') {
  return [{
    json: {
      chatId,
      responseType: 'course_selection',
      curso_input: text,
      stage: 'curso'
    }
  }];
}

if (session.stage === 'metodo_pago') {
  if (text.length < 2) {
    return [{
      json: {
        chatId,
        responseType: 'message',
        response: 'Por favor, indica un método de pago válido.',
        stage: 'metodo_pago'
      }
    }];
  }

  session.metodo_pago = text;
  session.stage = 'confirmar';

  return [{
    json: {
      chatId,
      responseType: 'confirmation',
      nombre_completo: session.nombre_completo,
      cedula_identidad: session.cedula_identidad,
      email: session.email,
      curso_id: session.curso_id,
      curso_nombre: session.curso_nombre,
      metodo_pago: session.metodo_pago,
      stage: 'confirmar'
    }
  }];
}

if (session.stage === 'confirmar') {
  if (normalized === 'si' || normalized === 'sí' || normalized === 'confirmar') {
    return [{
      json: {
        chatId,
        responseType: 'register',
        nombre_completo: session.nombre_completo,
        cedula_identidad: session.cedula_identidad,
        email: session.email,
        curso_id: session.curso_id,
        curso_nombre: session.curso_nombre,
        metodo_pago: session.metodo_pago
      }
    }];
  }

  if (normalized === 'no' || normalized === 'cancelar') {
    delete store.sessions[chatId];
    return [{
      json: {
        chatId,
        responseType: 'message',
        response: 'La inscripción no fue registrada. Si deseas comenzar nuevamente, escribe /inscribirme.'
      }
    }];
  }

  return [{
    json: {
      chatId,
      responseType: 'message',
      response: 'Por favor responde SI para confirmar la inscripción o NO para cancelarla.'
    }
  }];
}

return [{
  json: {
    chatId,
    responseType: 'message',
    response: 'No pude interpretar tu solicitud. Escribe /inscribirme para comenzar nuevamente.'
  }
}];

const input = $('Procesar conversación').first().json;
const courses = $input.all().map(item => item.json);

const chatId = input.chatId;
const store = $getWorkflowStaticData('global');
const session = store.sessions?.[chatId];

if (!session) {
  return [{
    json: {
      chatId,
      responseType: 'message',
      response: 'La sesión de inscripción expiró. Escribe /inscribirme para comenzar nuevamente.'
    }
  }];
}

const available = courses.filter(c => Number(c.cupos_disponibles) > 0 && c.activo === true);

if (available.length === 0) {
  return [{
    json: {
      chatId,
      responseType: 'message',
      response: 'Actualmente no hay cursos con cupos disponibles. Por favor intenta nuevamente más tarde.'
    }
  }];
}

let response = 'Estos son los cursos disponibles:\n\n';

for (const course of available) {
  response += `${course.id}. ${course.nombre}\n`;
  response += `   Modalidad: ${course.modalidad}\n`;
  response += `   Cupos disponibles: ${course.cupos_disponibles}\n\n`;
}

response += 'Escribe el número del curso que deseas seleccionar.';

session.stage = 'curso';

return [{
  json: {
    chatId,
    responseType: 'message',
    response,
    stage: 'curso'
  }
}];

const input = $('Procesar conversación').first().json;
const results = $input.all().map(item => item.json);
const chatId = input.chatId;
const store = $getWorkflowStaticData('global');
const session = store.sessions?.[chatId];

if (!session) {
  return [{
    json: {
      chatId,
      responseType: 'message',
      response: 'La sesión de inscripción expiró. Escribe /inscribirme para comenzar nuevamente.'
    }
  }];
}

const course = results[0];

if (!course) {
  return [{
    json: {
      chatId,
      responseType: 'message',
      response: 'El curso seleccionado no existe. Por favor escribe nuevamente el número de un curso válido.'
    }
  }];
}

if (!course.activo) {
  return [{
    json: {
      chatId,
      responseType: 'message',
      response: 'El curso seleccionado no se encuentra activo. Por favor selecciona otro curso.'
    }
  }];
}

if (Number(course.cupos_disponibles) <= 0) {
  return [{
    json: {
      chatId,
      responseType: 'message',
      response: `El curso "${course.nombre}" no tiene cupos disponibles actualmente. Por favor selecciona otro curso.`
    }
  }];
}

session.curso_id = course.id;
session.curso_nombre = course.nombre;
session.stage = 'metodo_pago';

return [{
  json: {
    chatId,
    responseType: 'message',
    response: `Has seleccionado: ${course.nombre}\n\nCupos disponibles: ${course.cupos_disponibles}\n\nAhora indica tu método de pago.`,
    stage: 'metodo_pago'
  }
}];

const data = $json;

return [{
  json: {
    chatId: data.chatId,
    responseType: 'message',
    response: `Estos son los datos de tu inscripción:\n\nNombre: ${data.nombre_completo}\nDocumento: ${data.cedula_identidad}\nCorreo: ${data.email}\nCurso: ${data.curso_nombre}\nMétodo de pago: ${data.metodo_pago}\n\n¿Deseas confirmar la inscripción? Responde SI o NO.`
  }
}];

const input = $('Procesar conversación').first().json;
const students = $input.all().map(item => item.json);
const existing = students[0];

return [{
  json: {
    ...input,
    existingStudentId: existing?.id || null
  }
}];

const input = $('Procesar estudiante').first().json;
const result = $input.first().json;

const studentId = input.existingStudentId || result.id;

return [{
  json: {
    ...input,
    studentId
  }
}];

const input = $('Preparar inscripción').first().json;
const registration = $input.first().json;
const inscription = Array.isArray(registration) ? registration[0] : registration;

const store = $getWorkflowStaticData('global');
if (store.sessions && store.sessions[input.chatId]) {
  delete store.sessions[input.chatId];
}

return [{
  json: {
    chatId: input.chatId,
    response: `✅ Inscripción realizada correctamente.\n\nNúmero de inscripción: #${inscription.id}\n\nEstudiante: ${input.nombre_completo}\nCurso: ${input.curso_nombre}\nMétodo de pago: ${input.metodo_pago}\n\nGracias por registrarte.`,
    registrationId: inscription.id
  }
}];
